  flex-wrap: wrap;
  justify-content: center;
  padding: 1.5rem 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  margin-bottom: 2rem;
}

.popular-tag {
  padding: 0.5rem 1rem;
  background: var(--bg-gray);
  border-radius: 20px;
  font-size: 0.85rem;
  color: var(--text-dark);
}

.popular-tag span {
  color: var(--text-muted);
  margin-left: 0.25rem;
}

/* Learn Page */
.welcome-cta {
  background: var(--primary);
  color: white;
  padding: 2.5rem;
  border-radius: 16px;
  text-align: center;
  margin-bottom: 3rem;
}

.welcome-cta h2 {
  font-size: 1.75rem;
  margin-bottom: 0.75rem;
}

.welcome-cta p {
  color: rgba(255,255,255,0.7);
  margin-bottom: 1.5rem;
}

.btn-primary {
  background: var(--accent);
  color: var(--primary);
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  font-weight: 600;
  border: none;
  cursor: pointer;
  display: inline-block;
}

.btn-primary:hover {
  background: #e99a28;
  text-decoration: none;
}

.curriculum-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.25rem;
  margin-bottom: 3rem;
}

.curriculum-card {
  background: var(--bg-gray);
  border-radius: 12px;
  padding: 1.5rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  transition: transform 0.2s, box-shadow 0.2s;
}

.curriculum-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
}

.curriculum-icon {
  width: 48px;
  height: 48px;
  background: var(--accent);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

.curriculum-card h3 {
  font-size: 1rem;
  font-weight: 600;
}

.section-block {
  margin-bottom: 3rem;
}

.section-block h2 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 1.25rem;
  color: var(--primary);
}

.daily-challenge {
  background: linear-gradient(135deg, #1a1a2e 0%, #2d2d5a 100%);
  color: white;
  padding: 2rem;
  border-radius: 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 3rem;
}

.daily-challenge h3 {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}

.daily-challenge p {
  color: rgba(255,255,255,0.7);
  font-size: 0.9rem;
}

.challenge-links a {
  color: var(--accent);
  font-weight: 600;
}

.courses-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.course-card {
  background: var(--bg-gray);
  padding: 1.25rem;
  border-radius: 10px;
  font-size: 0.9rem;
  font-weight: 500;
}

/* Donate Page */
.donate-hero {
  text-align: center;
  padding: 3rem 0;
}

.donate-hero h1 {
  font-size: 2.5rem;
  color: var(--primary);
  margin-bottom: 1rem;
}

.donate-hero p {
  max-width: 600px;
  margin: 0 auto;
  color: var(--text-muted);
  font-size: 1.1rem;
  line-height: 1.7;
}

.donation-form {
  background: var(--bg-gray);
  border-radius: 16px;
  padding: 2.5rem;
  max-width: 600px;
  margin: 0 auto 3rem;
}

.amount-tabs {
  display: flex;
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}

.amount-tab {
  flex: 1;
  padding: 1rem;
  background: white;
  border: 2px solid var(--border);
  border-radius: 10px;
  font-size: 1.25rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s;
}

.amount-tab:hover {
  border-color: var(--primary);
}

.amount-tab.active {
  background: var(--primary);
  color: white;
  border-color: var(--primary);
}

.donation-description {
  text-align: center;
  padding: 1.25rem;
  background: white;
  border-radius: 10px;
  margin-bottom: 1.5rem;
  font-size: 1rem;
}

.donate-submit {
  width: 100%;
  padding: 1rem;
  background: var(--accent);
  color: var(--primary);
  border: none;
  border-radius: 10px;
  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
}

.donate-submit:hover {
  background: #e99a28;
}

.donation-sublabel {
  text-align: center;
  color: var(--text-muted);
  font-size: 0.8rem;
  margin-top: 0.75rem;
}

.supporter-benefits {
  max-width: 600px;
  margin: 0 auto 3rem;
}

.supporter-benefits h2 {
  text-align: center;
  margin-bottom: 1.5rem;
  font-size: 1.5rem;
}

.benefits-list {
  list-style: none;
}

.benefits-list li {
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.benefit-icon {
  color: var(--accent);
}

.initiatives-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
  margin-bottom: 3rem;
}

.initiative-card {
  background: var(--bg-gray);
  padding: 1.5rem;
  border-radius: 12px;
}

.initiative-card h3 {
  font-size: 1rem;
  margin-bottom: 0.5rem;
  color: var(--primary);
}

.initiative-card p {
  color: var(--text-muted);
  font-size: 0.9rem;
}

.achievements-list {
  max-width: 700px;
  margin: 0 auto 3rem;
  list-style: none;
}

.achievements-list li {
  padding: 1rem 0;
  border-bottom: 1px solid var(--border);
  font-size: 1.1rem;
}

.achievements-list strong {
  color: var(--primary);
}

/* FAQ Accordion */
.faq-section {
  max-width: 700px;
  margin: 0 auto 3rem;
}

.faq-section h2 {
  text-align: center;
  margin-bottom: 1.5rem;
  font-size: 1.5rem;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-question {
  width: 100%;
  padding: 1.25rem 0;
  background: none;
  border: none;
  text-align: left;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--text-dark);
}

.faq-question:hover {
  color: var(--link-blue);
}

.faq-icon {
  transition: transform 0.3s;
}

.faq-item.active .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.faq-item.active .faq-answer {
  max-height: 500px;
}

.faq-answer p {
  padding-bottom: 1.25rem;
  color: var(--text-muted);
  line-height: 1.7;
}

/* Responsive */
@media (max-width: 1024px) {
  .article-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .featured-card {
    grid-template-columns: 1fr;
  }

  .featured-image {
    aspect-ratio: 16/9;
  }
}

@media (max-width: 768px) {
  .header-top {
    flex-wrap: wrap;
  }

  .search-bar {
    order: 3;
    max-width: 100%;
    margin: 1rem 0 0;
    width: 100%;
  }

  .nav-links {
    display: none;
  }

  .hamburger {
    display: block;
  }

  .article-grid {
    grid-template-columns: 1fr;
  }

  .footer-content {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .courses-grid {
    grid-template-columns: 1fr;
  }

  .initiatives-grid {
    grid-template-columns: 1fr;
  }

  .amount-tabs {
    flex-wrap: wrap;
  }

  .amount-tab {
    flex: 1 1 45%;
  }

  .daily-challenge {
    flex-direction: column;
    text-align: center;
    gap: 1.5rem;
  }

  .featured-title {
    font-size: 1.5rem;
  }

  .tag-header-content h1 {
    font-size: 1.75rem;
  }
}

/* OpenLearnHub - Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --primary: #0A0A23;
  --accent: #FEAC32;
  --link-blue: #002EAD;
  --bg-light: #FFFFFF;
  --bg-gray: #F7F8FA;
  --text-dark: #1a1a2e;
  --text-muted: #6B7280;
  --border: #E5E7EB;
  --shadow: 0 4px 6px -1px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background: var(--bg-light);
  color: var(--text-dark);
  line-height: 1.6;
}

a {
  color: var(--link-blue);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* Header */
.header {
  background: var(--primary);
  color: white;
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 2rem;
  max-width: 1400px;
  margin: 0 auto;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: white;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.logo-icon {
  background: var(--accent);
  color: var(--primary);
  width: 32px;
  height: 32px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-links a {
  color: rgba(255,255,255,0.85);
  font-weight: 500;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--accent);
  text-decoration: none;
}

.search-bar {
  flex: 1;
  max-width: 400px;
  margin: 0 2rem;
}

.search-bar input {
  width: 100%;
  padding: 0.625rem 1rem;
  border-radius: 8px;
  border: none;
  background: rgba(255,255,255,0.1);
  color: white;
  font-size: 0.875rem;
}

.search-bar input::placeholder {
  color: rgba(255,255,255,0.5);
}

.hamburger {
  display: none;
  background: none;
  border: none;
  color: white;
  cursor: pointer;
  padding: 0.5rem;
}

.mobile-nav {
  display: none;
  flex-direction: column;
  background: rgba(0,0,0,0.3);
  padding: 1rem 2rem;
}

.mobile-nav.active {
  display: flex;
}

.mobile-nav a {
  color: white;
  padding: 0.75rem 0;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

/* Banner */
.banner {
  background: var(--accent);
  color: var(--primary);
  text-align: center;
  padding: 0.875rem 1rem;
  font-weight: 600;
  font-size: 0.9rem;
}

/* Main Content */
.main {
  max-width: 1400px;
  margin: 0 auto;
  padding: 2rem;
}

/* Featured Article */
.featured-section {
  margin-bottom: 3rem;
}

.featured-card {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 2rem;
  background: var(--bg-gray);
  border-radius: 16px;
  overflow: hidden;
}

.featured-image {
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #1a1a2e 0%, #2d2d5a 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.featured-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.featured-tag {
  position: absolute;
  top: 1rem;
  left: 1rem;
  background: var(--accent);
  color: var(--primary);
  padding: 0.25rem 0.75rem;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
}

.featured-content {
  padding: 2.5rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.featured-title {
  font-size: 2rem;
  font-weight: 800;
  line-height: 1.2;
  margin-bottom: 1rem;
  color: var(--primary);
}

.featured-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.author-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: 600;
  font-size: 0.8rem;
}

/* Article Grid */
.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
}

.section-title {
  font-size: 1.5rem;
  font-weight: 700;
}

.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.article-card {
  background: white;
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid var(--border);
  transition: transform 0.2s, box-shadow 0.2s;
}

.article-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.card-thumbnail {
  aspect-ratio: 16/9;
  background: linear-gradient(135deg, #667 0%, #999 100%);
  position: relative;
}

.card-tag {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  padding: 0.25rem 0.625rem;
  border-radius: 4px;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
}

.tag-ai { background: #FEF3C7; color: #92400E; }
.tag-web-scraping { background: #DBEAFE; color: #1E40AF; }
.tag-databases { background: #D1FAE5; color: #065F46; }
