.initiative-card p {
  color: var(--text-muted);
  font-size: 0.9rem;
}

.achievements-list {
  max-width: 700px;
  margin: 0 auto 3rem;
  list-style: none;
}

.achievements-list li {
  padding: 1rem 0;
  border-bottom: 1px solid var(--border);
  font-size: 1.1rem;
}

.achievements-list strong {
  color: var(--primary);
}

/* FAQ Accordion */
.faq-section {
  max-width: 700px;
  margin: 0 auto 3rem;
}

.faq-section h2 {
  text-align: center;
  margin-bottom: 1.5rem;
  font-size: 1.5rem;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-question {
  width: 100%;
  padding: 1.25rem 0;
  background: none;
  border: none;
  text-align: left;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--text-dark);
}

.faq-question:hover {
  color: var(--link-blue);
}

.faq-icon {
  transition: transform 0.3s;
}

.faq-item.active .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.faq-item.active .faq-answer {
  max-height: 500px;
}

.faq-answer p {
  padding-bottom: 1.25rem;
  color: var(--text-muted);
  line-height: 1.7;
}

/* Responsive */
@media (max-width: 1024px) {
  .article-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .featured-card {
    grid-template-columns: 1fr;
  }

  .featured-image {
    aspect-ratio: 16/9;
  }
}

@media (max-width: 768px) {
  .header-top {
    flex-wrap: wrap;
  }

  .search-bar {
    order: 3;
    max-width: 100%;
    margin: 1rem 0 0;
    width: 100%;
  }

  .nav-links {
    display: none;
  }

  .hamburger {
    display: block;
