  .article-grid {
    grid-template-columns: 1fr;
  }

  .footer-content {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .courses-grid {
    grid-template-columns: 1fr;
  }

  .initiatives-grid {
    grid-template-columns: 1fr;
  }

  .amount-tabs {
    flex-wrap: wrap;
  }

  .amount-tab {
    flex: 1 1 45%;
  }

  .daily-challenge {
    flex-direction: column;
    text-align: center;
    gap: 1.5rem;
  }

  .featured-title {
    font-size: 1.5rem;
  }

  .tag-header-content h1 {
    font-size: 1.75rem;
  }
