/* OpenLearnHub - Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --primary: #0A0A23;
  --accent: #FEAC32;
  --link-blue: #002EAD;
  --bg-light: #FFFFFF;
  --bg-gray: #F7F8FA;
  --text-dark: #1a1a2e;
  --text-muted: #6B7280;
  --border: #E5E7EB;
  --shadow: 0 4px 6px -1px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background: var(--bg-light);
  color: var(--text-dark);
  line-height: 1.6;
}

a {
  color: var(--link-blue);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* Header */
.header {
  background: var(--primary);
  color: white;
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 2rem;
  max-width: 1400px;
  margin: 0 auto;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: white;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.logo-icon {
  background: var(--accent);
  color: var(--primary);
  width: 32px;
  height: 32px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-links a {
  color: rgba(255,255,255,0.85);
  font-weight: 500;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--accent);
  text-decoration: none;
}

.search-bar {
  flex: 1;
  max-width: 400px;
  margin: 0 2rem;
}

.search-bar input {
  width: 100%;
  padding: 0.625rem 1rem;
  border-radius: 8px;
  border: none;
  background: rgba(255,255,255,0.1);
  color: white;
  font-size: 0.875rem;
}

.search-bar input::placeholder {
  color: rgba(255,255,255,0.5);
}

.hamburger {
  display: none;
  background: none;
  border: none;
  color: white;
  cursor: pointer;
  padding: 0.5rem;
}

.mobile-nav {
  display: none;
  flex-direction: column;
  background: rgba(0,0,0,0.3);
  padding: 1rem 2rem;
}

.mobile-nav.active {
  display: flex;
}

.mobile-nav a {
  color: white;
  padding: 0.75rem 0;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

/* Banner */
.banner {
  background: var(--accent);
  color: var(--primary);
  text-align: center;
  padding: 0.875rem 1rem;
  font-weight: 600;
  font-size: 0.9rem;
}

/* Main Content */
.main {
  max-width: 1400px;
  margin: 0 auto;
  padding: 2rem;
}

/* Featured Article */
.featured-section {
  margin-bottom: 3rem;
}

.featured-card {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 2rem;
  background: var(--bg-gray);
  border-radius: 16px;
  overflow: hidden;
}

.featured-image {
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #1a1a2e 0%, #2d2d5a 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.featured-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.featured-tag {
  position: absolute;
  top: 1rem;
  left: 1rem;
  background: var(--accent);
  color: var(--primary);
  padding: 0.25rem 0.75rem;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
}

.featured-content {
  padding: 2.5rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.featured-title {
  font-size: 2rem;
  font-weight: 800;
  line-height: 1.2;
  margin-bottom: 1rem;
  color: var(--primary);
}

.featured-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.author-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: 600;
  font-size: 0.8rem;
}

/* Article Grid */
.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
}

.section-title {
  font-size: 1.5rem;
  font-weight: 700;
}

.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.article-card {
  background: white;
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid var(--border);
  transition: transform 0.2s, box-shadow 0.2s;
}

.article-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.card-thumbnail {
  aspect-ratio: 16/9;
  background: linear-gradient(135deg, #667 0%, #999 100%);
  position: relative;
}

.card-tag {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  padding: 0.25rem 0.625rem;
  border-radius: 4px;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
}

.tag-ai { background: #FEF3C7; color: #92400E; }
.tag-web-scraping { background: #DBEAFE; color: #1E40AF; }
.tag-databases { background: #D1FAE5; color: #065F46; }
.tag-elasticsearch { background: #EDE9FE; color: #5B21B6; }
.tag-data-engineering { background: #FCE7F3; color: #9D174D; }
.tag-python { background: #FEF3C7; color: #92400E; }
.tag-node-js { background: #D1FAE5; color: #065F46; }
.tag-google-sheets { background: #DBEAFE; color: #1E40AF; }

.card-content {
  padding: 1.25rem;
}

.card-title {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 0.75rem;
  color: var(--text-dark);
}

.card-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.card-meta .author-avatar {
  width: 24px;
  height: 24px;
  font-size: 0.65rem;
}

/* Load More Button */
.load-more-container {
  text-align: center;
  margin-top: 2.5rem;
}

.btn-load-more {
  background: var(--primary);
  color: white;
  border: none;
  padding: 0.875rem 2rem;
  border-radius: 8px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
}

.btn-load-more:hover {
  background: #1a1a3a;
}

/* Footer */
.footer {
  background: var(--primary);
  color: white;
  padding: 3rem 2rem;
  margin-top: 4rem;
}

.footer-content {
  max-width: 1400px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 3rem;
}

.footer-mission {
  font-size: 0.9rem;
  line-height: 1.7;
  color: rgba(255,255,255,0.7);
}

.footer-section h4 {
  color: var(--accent);
  margin-bottom: 1rem;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-section ul {
  list-style: none;
}

.footer-section li {
  margin-bottom: 0.5rem;
}

.footer-section a {
  color: rgba(255,255,255,0.7);
  font-size: 0.875rem;
}

.footer-section a:hover {
  color: var(--accent);
}

.trending-guides {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.5rem;
}

.trending-guides a {
  background: rgba(255,255,255,0.1);
  padding: 0.25rem 0.625rem;
  border-radius: 4px;
  font-size: 0.8rem;
}

/* Tag Pages */
.tag-header-content {
  text-align: center;
  padding: 3rem 0;
}

.tag-header-content h1 {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 0.5rem;
}

.tag-header-content .post-count {
  color: var(--text-muted);
  font-size: 1.1rem;
}

.popular-tags {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  justify-content: center;
  padding: 1.5rem 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  margin-bottom: 2rem;
}

.popular-tag {
  padding: 0.5rem 1rem;
  background: var(--bg-gray);
  border-radius: 20px;
  font-size: 0.85rem;
  color: var(--text-dark);
}

.popular-tag span {
  color: var(--text-muted);
  margin-left: 0.25rem;
}

/* Learn Page */
.welcome-cta {
  background: var(--primary);
  color: white;
  padding: 2.5rem;
  border-radius: 16px;
  text-align: center;
  margin-bottom: 3rem;
}

.welcome-cta h2 {
  font-size: 1.75rem;
  margin-bottom: 0.75rem;
}

.welcome-cta p {
  color: rgba(255,255,255,0.7);
  margin-bottom: 1.5rem;
}

.btn-primary {
  background: var(--accent);
